#!/usr/bin/env node
/**
 * copy-ecosystem
 *
 * Copies data/ecosystem.json into site/ecosystem.json so the site is
 * self-contained: no runtime fetch ever leaves site/. Run this after
 * bin/snapshot.mjs produces a new snapshot, and before deploying.
 *
 * Deliberately just a copy, not a template render: index.html's static
 * roster is hand-authored from the same snapshot, not generated by this
 * script. If you re-run snapshot.mjs and the ecosystem has actually
 * changed, update the static roster and the numbers in the status board
 * by hand too (see README.md's Limitations section).
 */

import { copyFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const src = join(root, 'data', 'ecosystem.json');
const destDir = join(root, 'site');
const dest = join(destDir, 'ecosystem.json');

mkdirSync(destDir, { recursive: true });
copyFileSync(src, dest);
process.stdout.write(`copy-ecosystem: ${src} -> ${dest}\n`);
